/* GENERATED by gen_hcon_rejectlog.py -- models are generated.
   source view  : BJAZ_POLICY_SUMMARY   (run: opus_health_delta3)
   target       : HUB_LOCATION
   reject class : content_hash_per_operand_guarded
   reject slot  : expression
   operands     : INSURED_ADDRESS, PINCODE
   This is the COMPLEMENT of the hub feed's WHERE clause. A row here is a row that
   did NOT reach a hub, link or satellite. Counted, never absorbed.
*/

select
    'BJAZ_POLICY_SUMMARY' as SOURCE_VIEW,
    'opus_health_delta3' as SOURCE_RUN,
    'HUB_LOCATION' as TARGET_TABLE,
    'content_hash_per_operand_guarded' as REJECT_CLASS,
    'expression' as REJECT_SLOT,
    'INSURED_ADDRESS, PINCODE' as KEY_OPERANDS,
    '|' as DEGENERATE_VALUE,
    false as SILENT_DROP
from {{ ref('stage_policy_summary') }}
where (md5(normalise(upper(nullif(coalesce(nullif(trim(INSURED_ADDRESS),''),'') || '|' || coalesce(nullif(trim(PINCODE),''),''), '|'))))) is null
   or (HUB_LOCATION_BK__INSURED_ADDRESS_PINCODE) = '|'
